#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────
#
# Sets up what .github/workflows/release.yml needs to sign, notarise and
# publish: the `release` GitHub environment and its 7 secrets.
#
#   ./scripts/setup-release-signing.sh
#
# Safe to re-run. The two non-secret IDs are remembered outside the repo;
# certificates and passwords are never written to disk by this script.

TOTAL_STAGES=7

REPO="Busnes-app/KyPost-for-Mac"
TEAM_ID="TATYN4X57D"
ENVIRONMENT="release"
EXPECTED_SECRETS=(
  APP_STORE_CONNECT_PRIVATE_KEY APP_STORE_CONNECT_KEY_ID APP_STORE_CONNECT_ISSUER_ID
  APPLE_DEVELOPMENT_CERTIFICATE APPLE_DEVELOPMENT_CERTIFICATE_PASSWORD
  DEVELOPER_ID_CERTIFICATE DEVELOPER_ID_CERTIFICATE_PASSWORD
)
# Where exported .p12 files are saved, so the last stage can delete them.
EXPORT_DIR="$HOME/Desktop/kypost-signing"
# Only the key ID and issuer ID land here: neither is a secret.
ENV_FILE="$HOME/.config/kypost/release-signing.env"
mkdir -p "$(dirname "$ENV_FILE")"

# The library's set_secret writes repository secrets. release.yml reads these
# from the `release` environment, so they go there instead.
set_env_secret() {
  local name="$1" value="$2"
  if printf '%s' "$value" | gh secret set "$name" --repo "$REPO" --env "$ENVIRONMENT" >/dev/null 2>&1; then
    WRITTEN_SECRET+=("$name")
    printf '  %s✓ set%s %s on the %s environment\n' "$GREEN" "$RESET" "$name" "$ENVIRONMENT"
  else
    SKIPPED+=("secret $name (gh secret set $name --repo $REPO --env $ENVIRONMENT)")
    warn "could not set $name; it is listed at the end"
  fi
}

# ask_file VAR "Prompt" reads a path (drag the file into Terminal works) and
# repeats until the file exists.
ask_file() {
  local var="$1" prompt="$2" path
  while true; do
    ask "$var" "$prompt"
    path="${!var}"
    path="${path%\'}"; path="${path#\'}"; path="${path%\"}"; path="${path#\"}"
    path="${path%"${path##*[![:space:]]}"}"
    path="${path/#\~/$HOME}"
    path="${path//\\ / }"
    if [[ -f "$path" ]]; then printf -v "$var" '%s' "$path"; return; fi
    warn "no file at: $path"
  done
}

# check_p12 FILE PASSWORD PREFIX: imports the .p12 into a throwaway keychain,
# exactly as release.yml does, and prints the identity whose name starts with
# PREFIX. Fails on a wrong password, a certificate without its private key, or
# the wrong kind of certificate.
check_p12() {
  local file="$1" password="$2" prefix="$3" keychain kc_pass identity
  keychain=$(mktemp -d)/check.keychain-db
  kc_pass=$(uuidgen)
  security create-keychain -p "$kc_pass" "$keychain" >/dev/null 2>&1
  if ! security import "$file" -k "$keychain" -P "$password" >/dev/null 2>&1; then
    security delete-keychain "$keychain" >/dev/null 2>&1 || true
    return 1
  fi
  identity=$(security find-identity -p codesigning "$keychain" 2>/dev/null \
    | sed -n "s/.*\"\\(${prefix}[^\"]*\\)\".*/\\1/p" | head -1)
  security delete-keychain "$keychain" >/dev/null 2>&1 || true
  [[ -n "$identity" ]] || return 2
  printf '%s' "$identity"
}

# export_identity LABEL PREFIX CERT_SECRET PASSWORD_SECRET: one Keychain
# Access export, checked, then stored as two secrets.
export_identity() {
  local label="$1" prefix="$2" cert_secret="$3" pass_secret="$4" file password identity rc
  step "Open Keychain Access (it is opening now), select the ${BOLD}login${RESET} keychain, then ${BOLD}My Certificates${RESET}."
  open -a "Keychain Access" >/dev/null 2>&1 || warn "open Keychain Access yourself (Applications → Utilities)"
  step "Find ${BOLD}${label}${RESET}. It must have a ▸ arrow with a private key under it."
  step "Right-click it → ${BOLD}Export…${RESET} → format ${BOLD}Personal Information Exchange (.p12)${RESET}."
  step "Save it in ${BOLD}${EXPORT_DIR}${RESET} (created for you), and choose a password."
  mkdir -p "$EXPORT_DIR"
  note "If macOS asks for your login password to allow the export, that is expected."
  printf '\n'
  while true; do
    ask_file P12_PATH "Drag the .p12 file here (or type its path), then Enter:"
    ask_secret P12_PASSWORD "The password you chose for that export (hidden):"
    file="$P12_PATH"; password="$P12_PASSWORD"
    rc=0; identity=$(check_p12 "$file" "$password" "$prefix") || rc=$?
    case "$rc" in
      0) printf '  %s✓ checked%s %s\n' "$GREEN" "$RESET" "$identity"; break ;;
      1) warn "that file would not import: wrong password, or it is not a .p12. Try again." ;;
      *) warn "no '${prefix}' identity with a private key in that file."
         note "Export the certificate from My Certificates, with its private key, not from Certificates." ;;
    esac
  done
  if [[ "$identity" != *"($TEAM_ID)"* && "$prefix" == "Developer ID Application" ]]; then
    warn "this identity is not for team $TEAM_ID: $identity"
    confirm "Use it anyway?" || { SKIPPED+=("$cert_secret / $pass_secret (wrong team)"); return; }
  fi
  set_env_secret "$cert_secret" "$(base64 -i "$file" | tr -d '\n')"
  set_env_secret "$pass_secret" "$password"
  unset P12_PASSWORD
}

banner "KyPost release signing setup"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Check this Mac is ready"
say "This sets up the ${BOLD}${ENVIRONMENT}${RESET} environment on ${BOLD}${REPO}${RESET} and its 7 secrets,"
say "so pushing a version tag signs, notarises and publishes the Mac app."
printf '\n'
command -v gh >/dev/null 2>&1 || { warn "GitHub CLI missing: brew install gh"; exit 1; }
gh auth status >/dev/null 2>&1 || { warn "not signed in to GitHub: run  gh auth login"; exit 1; }
printf '  %s✓%s GitHub CLI signed in as %s\n' "$GREEN" "$RESET" "$(gh api user --jq .login)"
if [[ "$(gh api "repos/$REPO" --jq .permissions.admin 2>/dev/null)" != "true" ]]; then
  warn "your GitHub account is not an admin of $REPO; only an admin can create environments."
  exit 1
fi
printf '  %s✓%s admin on %s\n' "$GREEN" "$RESET" "$REPO"
xcrun --find notarytool >/dev/null 2>&1 || { warn "Xcode command-line tools missing: xcode-select --install"; exit 1; }
printf '  %s✓%s Xcode tools found\n\n' "$GREEN" "$RESET"
pause "Press Enter to continue"

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Create the '${ENVIRONMENT}' environment on GitHub"
say "The secrets live on an environment, not the repo, so only release runs can read them."
say "It will be limited to ${BOLD}v*${RESET} tags, and each run waits for ${BOLD}your approval${RESET}."
printf '\n'
if gh api "repos/$REPO/environments/$ENVIRONMENT" >/dev/null 2>&1; then
  printf '  %s✓%s the environment already exists; leaving its settings as they are\n' "$GREEN" "$RESET"
elif confirm "Create it now?"; then
  reviewer_id=$(gh api user --jq .id)
  gh api -X PUT "repos/$REPO/environments/$ENVIRONMENT" --input - >/dev/null <<JSON
{"reviewers":[{"type":"User","id":$reviewer_id}],
 "deployment_branch_policy":{"protected_branches":false,"custom_branch_policies":true}}
JSON
  gh api -X POST "repos/$REPO/environments/$ENVIRONMENT/deployment-branch-policies" \
    -f name='v*' -f type=tag >/dev/null
  printf '  %s✓ created%s %s: tags v* only, you approve each run\n' "$GREEN" "$RESET" "$ENVIRONMENT"
else
  warn "nothing below can be stored without it. Re-run when ready."
  exit 1
fi
pause "Press Enter to continue"

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "App Store Connect API key"
say "This key lets the release job notarise the Mac app and upload iOS builds."
open_url "https://appstoreconnect.apple.com/access/integrations/api"
step "Under ${BOLD}Team Keys${RESET}, copy the ${BOLD}Issuer ID${RESET} shown above the list."
step "Find your key in the list and check its ${BOLD}Access${RESET} column says ${BOLD}Admin${RESET}."
note "Not Admin, or no key file? Click +, choose Admin, Generate, then Download API Key."
note "A key file can be downloaded only once."
printf '\n'
default_p8="$HOME/Documents/AuthKey_QLC7CAQ73G.p8"
[[ -f "$default_p8" && -z "$(_existing ASC_KEY_FILE || true)" ]] && write_env ASC_KEY_FILE "$default_p8" >/dev/null
note "The key file found on this Mac is filled in; press Enter to use it."
ask_file ASC_KEY_FILE "Path to the AuthKey_XXXXXXXXXX.p8 file:"
ASC_KEY_ID=$(basename "$ASC_KEY_FILE" .p8); ASC_KEY_ID="${ASC_KEY_ID#AuthKey_}"
say "Key ID (from the file name): ${BOLD}${ASC_KEY_ID}${RESET}"
while true; do
  ask ASC_ISSUER_ID "Paste the Issuer ID:"
  ASC_ISSUER_ID=$(printf '%s' "$ASC_ISSUER_ID" | tr -d '[:space:]')
  [[ "$ASC_ISSUER_ID" =~ ^[0-9a-fA-F]{8}-([0-9a-fA-F]{4}-){3}[0-9a-fA-F]{12}$ ]] && break
  warn "an Issuer ID looks like 69a6de70-1234-47e3-e053-5b8c7c11a4d1. Try again."
done
confirm "Does that key's Access column say Admin?" \
  || warn "release.yml's App Store export needs Admin; the Mac release still works without it."
say "Checking the key and Issuer ID with Apple…"
if xcrun notarytool history --key "$ASC_KEY_FILE" --key-id "$ASC_KEY_ID" \
     --issuer "$ASC_ISSUER_ID" >/dev/null 2>&1; then
  printf '  %s✓ Apple accepted%s the key and Issuer ID\n' "$GREEN" "$RESET"
else
  warn "Apple refused this key/Issuer ID pair (wrong Issuer ID, or the key was revoked)."
  confirm "Store them anyway?" || { warn "re-run when you have the right values"; exit 1; }
fi
write_env ASC_KEY_FILE "$ASC_KEY_FILE"
write_env ASC_ISSUER_ID "$ASC_ISSUER_ID"
set_env_secret APP_STORE_CONNECT_PRIVATE_KEY "$(base64 -i "$ASC_KEY_FILE" | tr -d '\n')"
set_env_secret APP_STORE_CONNECT_KEY_ID "$ASC_KEY_ID"
set_env_secret APP_STORE_CONNECT_ISSUER_ID "$ASC_ISSUER_ID"
pause "Press Enter to continue"

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Export your Apple Development certificate"
say "The release job archives with this certificate before re-signing for distribution."
note "On this Mac it is: Apple Development: Matthew Beacher (24QPD67655)"
printf '\n'
export_identity "Apple Development: …" "Apple Development" \
  APPLE_DEVELOPMENT_CERTIFICATE APPLE_DEVELOPMENT_CERTIFICATE_PASSWORD
pause "Press Enter to continue"

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Create a Developer ID Application certificate"
say "This is what lets people open the downloaded Mac app without a warning."
warn "Only the Account Holder of team ${TEAM_ID} can create one."
printf '\n'
if security find-identity -v -p codesigning | grep -q "Developer ID Application: .*(${TEAM_ID})"; then
  printf '  %s✓%s already in your keychain:\n' "$GREEN" "$RESET"
  note "$(security find-identity -v -p codesigning | sed -n "s/.*\"\\(Developer ID Application: .*(${TEAM_ID})\\)\".*/\\1/p" | head -1)"
else
  step "Xcode → ${BOLD}Settings…${RESET} (⌘,) → ${BOLD}Accounts${RESET} → select your Apple ID → team ${TEAM_ID}."
  step "Click ${BOLD}Manage Certificates…${RESET} → ${BOLD}+${RESET} (bottom left) → ${BOLD}Developer ID Application${RESET}."
  step "Click Done. Xcode puts it, with its private key, in your login keychain."
  note "No Developer ID Application option? You are not the Account Holder: ask them to"
  note "create it, export it as .p12, and send it to you with its password."
  open -a Xcode >/dev/null 2>&1 || true
  printf '\n'
  pause "Press Enter once it is created (or you have the .p12 file)"
fi

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Export the Developer ID Application certificate"
note "Got a .p12 from the Account Holder instead? Skip Keychain Access and drag that file in."
printf '\n'
export_identity "Developer ID Application: … (${TEAM_ID})" "Developer ID Application" \
  DEVELOPER_ID_CERTIFICATE DEVELOPER_ID_CERTIFICATE_PASSWORD
pause "Press Enter to continue"

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Check everything is in place"
present=$(gh secret list --repo "$REPO" --env "$ENVIRONMENT" --json name --jq '.[].name' 2>/dev/null || true)
missing=0
for name in "${EXPECTED_SECRETS[@]}"; do
  if grep -qxF "$name" <<<"$present"; then
    printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$name"
  else
    printf '  %s✗%s %s\n' "$RED" "$RESET" "$name"; missing=$((missing + 1))
  fi
done
printf '\n'
if (( missing )); then
  warn "$missing secret(s) missing. Re-run this wizard to fill them in."
else
  printf '  %sAll 7 secrets are set.%s Release with:\n' "$GREEN" "$RESET"
  note "  git tag v<version> && git push origin v<version>"
fi
if [[ -d "$EXPORT_DIR" ]] && ls "$EXPORT_DIR"/*.p12 >/dev/null 2>&1; then
  printf '\n'
  say "The exported .p12 files in $EXPORT_DIR hold your private keys."
  say "They are now stored in GitHub and still in your keychain, so the copies aren't needed."
  if confirm "Delete them?"; then
    rm -f "$EXPORT_DIR"/*.p12 && rmdir "$EXPORT_DIR" 2>/dev/null || true
    printf '  %s✓ deleted%s\n' "$GREEN" "$RESET"
  else
    SKIPPED+=("delete the .p12 files in $EXPORT_DIR")
  fi
fi
pause "Press Enter to finish"

finish
